# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    nodes, edges, answers = payload['nodes'], {}, []
    for operation in payload['operations']:
        action = operation['op']
        if action in ('add', 'remove'):
            key = tuple(sorted((operation['a'], operation['b'])))
            if action == 'add':
                edges[key] = 1
            else:
                edges[key] = 0
            continue
        adjacency = {node: set() for node in nodes}
        for (a, b), count in edges.items():
            if count:
                adjacency[a].add(b)
                adjacency[b].add(a)
        groups = {}
        group_count = 0
        for root in nodes:
            if root in groups:
                continue
            stack = [root]
            groups[root] = group_count
            while stack:
                for child in adjacency[stack.pop()]:
                    if child not in groups:
                        groups[child] = group_count
                        stack.append(child)
            group_count += 1
        if action == 'components':
            answers.append(group_count)
        else:
            answers.append(groups[operation['a']] == groups[operation['b']])
    return answers

